<?php
require '/app/harness.php';$GLOBALS['plugin_runtime']='/advanced-runtime';
function advancedReject($fn){try{$fn();}catch(InvalidArgumentException|RuntimeException $e){return;}throw new LogicException('Expected rejection');}
function promoteRows(){return [['name'=>'cache/base','type'=>'filesystem','guid'=>'10','origin'=>'-','createtxg'=>'1'],['name'=>'cache/base@first','type'=>'snapshot','guid'=>'11','origin'=>'-','createtxg'=>'2'],['name'=>'cache/base@fork','type'=>'snapshot','guid'=>'12','origin'=>'-','createtxg'=>'3'],['name'=>'cache/base@later','type'=>'snapshot','guid'=>'13','origin'=>'-','createtxg'=>'5'],['name'=>'cache/clone','type'=>'filesystem','guid'=>'14','origin'=>'cache/base@fork','createtxg'=>'4']];}
check('promote preview identifies only moved snapshots and dependency reversal',function(){ $p=zfsmPromotePlan('cache/clone',promoteRows());same(['cache/base@first','cache/base@fork'],array_column($p['affected_snapshots'],'name'));same('cache/base',$p['origin_dataset']);same(true,$p['can_proceed']); });
check('conflicting promoted snapshot names block before native promote',function(){ $rows=promoteRows();$rows[]=['name'=>'cache/clone@first','type'=>'snapshot','guid'=>'15','origin'=>'-','createtxg'=>'6'];$p=zfsmPromotePlan('cache/clone',$rows);same(false,$p['can_proceed']);same(['cache/clone@first'],$p['conflicts']); });
check('nonclone and incomplete promote inventory reject instead of guessing',function(){advancedReject(fn()=>zfsmPromotePlan('cache/base',promoteRows()));$rows=promoteRows();unset($rows[2]);advancedReject(fn()=>zfsmPromotePlan('cache/clone',$rows));});
check('native promote scope parses mixed dataset and snapshot rows without normalizing origin dash away',function(){ $rows=promoteRows();$columns=['name','type','guid','origin','createtxg','userrefs'];$text=implode("\n",array_map(fn($r)=>implode("\t",array_map(fn($c)=>$r[$c]??'-',$columns)),$rows));expectProcess('zfs',['list','-H','-p','-r','-t','filesystem,volume,snapshot','-o',implode(',',$columns),'cache'],$text);$p=zfsmPromoteScope('cache/clone');same('-',$p['original']['origin']);same(2,count($p['affected_snapshots'])); });
check('pool root snapshots do not invalidate an unrelated clone promote review',function(){
 $rows=promoteRows();$rows[]=['name'=>'cache','type'=>'filesystem','guid'=>'1','origin'=>'-','createtxg'=>'1'];$rows[]=['name'=>'cache@root','type'=>'snapshot','guid'=>'2','origin'=>'-','createtxg'=>'1'];$columns=['name','type','guid','origin','createtxg','userrefs'];$text=implode("\n",array_map(fn($r)=>implode("\t",array_map(fn($c)=>$r[$c]??'-',$columns)),$rows));expectProcess('zfs',['list','-H','-p','-r','-t','filesystem,volume,snapshot','-o',implode(',',$columns),'cache'],$text);same(true,zfsmPromoteScope('cache/clone')['can_proceed']);
});
check('quota fields restrict numeric POSIX identity and bounded native counts',function(){same(['property'=>'userquota@99','value'=>'1048576'],zfsmQuotaInput(['kind'=>'user','id'=>'99','value'=>'1048576']));same('groupobjquota@100',zfsmQuotaInput(['kind'=>'groupobj','id'=>'100','value'=>'none'])['property']);foreach([['kind'=>'project','id'=>'1','value'=>'9'],['kind'=>'user','id'=>'root;id','value'=>'9'],['kind'=>'user','id'=>'1','value'=>'inherit'],['kind'=>'userobj','id'=>'1','value'=>'1G']] as $input)advancedReject(fn()=>zfsmQuotaInput($input));});
check('quota inventory distinguishes unsupported object fields and numeric usage',function(){same([['type'=>'POSIX User','id'=>'99','used'=>'1024','quota'=>'4096','objects_used'=>'4','objects_quota'=>'8']],zfsmQuotaParse("POSIX User\t99\t1024\t4096\t4\t8\n",true));same(null,zfsmQuotaParse("POSIX User\t99\tsecret\t4096\n",false));same(null,zfsmQuotaParse("POSIX User\troot\t1\t2\n",false));});
check('review identity and dependencies invalidate consumed operation preview',function(){ $scope=['kind'=>'promote','name'=>'cache/clone','guid'=>'14'];$p=zfsmOperationPreview($scope,'secret');same($scope,zfsmOperationConsume($p,'secret',$scope));advancedReject(fn()=>zfsmOperationConsume($p,'secret',$scope));$p=zfsmOperationPreview($scope,'secret');advancedReject(fn()=>zfsmOperationConsume($p,'secret',$scope+['changed'=>true])); });
check('snapshot provenance matches dataset and snapshot GUID rather than a native looking name',function(){ $snapshots=[['name'=>'cache/base@autosnap_manual','guid'=>'11'],['name'=>'cache/base@fork','guid'=>'12']];$store=['owned_snapshots'=>['cache/base@autosnap_manual'=>['guid'=>'999','dataset_guid'=>'10','policy_id'=>'bad'],'cache/base@fork'=>['guid'=>'12','dataset_guid'=>'10','policy_id'=>'abc']],'replications'=>['def'=>['source'=>'cache/base']]];zfsmAnnotateSnapshots($snapshots,['cache/base'=>'10'],$store,[]);same('Unknown',$snapshots[0]['provenance']);same('Managed policy abc',$snapshots[1]['provenance']);same(['def'],$snapshots[1]['replication_refs']);same(null,$snapshots[1]['last_verified_replication']);});
check('dataset space limits validate exact binary sizes without floating point rounding',function(){same('1073741824',zfsmSpaceLimitBytes('1G'));same('9223372036854775807',zfsmSpaceLimitBytes('9223372036854775807'));same('0',zfsmSpaceLimitBytes('none'));advancedReject(fn()=>zfsmSpaceLimitBytes('9E'));advancedReject(fn()=>zfsmSpaceLimitBytes('1;id'));advancedReject(fn()=>zfsmSpaceLimitBytes('inherit'));});
check('zvol quota cannot enter the reviewed mutation path',function(){expectProcess('zfs',['list','-H','-p','-o','name,type,guid','-t','filesystem,volume,snapshot','cache/vol'],"cache/vol\tvolume\t90");advancedReject(fn()=>zfsmSpacePropertyScope('cache/vol','quota','1G'));});
check('quota usage alerts derive byte and object ratios from native evidence only',function(){$rows=[['type'=>'POSIX User','id'=>'99','used'=>'85','quota'=>'100','objects_used'=>'95','objects_quota'=>'100'],['type'=>'POSIX Group','id'=>'100','used'=>'0','quota'=>'0','objects_used'=>null,'objects_quota'=>null]];$a=zfsmQuotaUsageAlerts($rows,['space_warning_percent'=>80,'space_critical_percent'=>90]);same(['warning','error'],array_column($a,'severity'));});
finishTests();
